/**
 * Thin stdout/stderr/exit-code layer.
 *
 * Why this exists: CPython writes to `sys.stdout` / `sys.stderr` and then lets
 * the interpreter shut down, flushing both streams.  In Node, calling
 * `process.exit()` can truncate a pending `write()` on a pipe, so we NEVER call
 * it.  Instead we set `process.exitCode` and let the event loop drain
 * naturally -- that is the documented way to guarantee a full flush.
 */

/** Write text to stdout (no trailing newline is added). */
export function writeStdout(text) {
  if (text === '') return;
  process.stdout.write(text);
}

/** Write text to stderr (no trailing newline is added). */
export function writeStderr(text) {
  if (text === '') return;
  process.stderr.write(text);
}

/**
 * Request process exit status `code`.
 *
 * Deliberately `process.exitCode = N` rather than `process.exit(N)`: a large
 * stdout payload (e.g. a 4300-digit integer) would otherwise be cut off when
 * stdout is a pipe.
 */
export function setExitCode(code) {
  process.exitCode = code;
}

/**
 * The small slice of the Unicode Character Database that CPython's `int()` and
 * `repr()` depend on.
 *
 * Two of the properties below look interchangeable but are NOT, and conflating
 * them is the single easiest way to break parity:
 *
 *   * `int()` strips leading/trailing characters that have the Unicode
 *     `White_Space` property.
 *   * `repr()` escapes characters that are not `str.isprintable()`.
 *
 * U+00A0 (NBSP) and U+3000 (IDEOGRAPHIC SPACE) are in *both* sets: `int()`
 * happily strips them, yet if the literal is invalid for some other reason the
 * very same characters come back escaped as `\xa0` / `　` in the error
 * message.  Conversely U+200B (ZERO WIDTH SPACE) is NOT White_Space -- it makes
 * `int()` fail -- but it is non-printable, so it gets escaped.  Both facts
 * coexist; they are not a contradiction.
 */

/**
 * Unicode `White_Space`, exactly as CPython's `Py_UNICODE_ISSPACE` sees it for
 * `int()`.  Node's `\p{White_Space}` matches precisely the accepted set
 * (U+0009..U+000D, U+0020, U+0085, U+00A0, U+1680, U+2000..U+200A, U+2028,
 * U+2029, U+202F, U+205F, U+3000) and correctly rejects U+001C..U+001F and
 * U+200B.
 *
 * Do NOT substitute `String.prototype.trim()`: its whitespace set includes
 * U+FEFF and excludes U+0085, so it is wrong in both directions.
 */
const WHITE_SPACE_RE = /^\p{White_Space}$/u;

/** Unicode General_Category=Nd -- the only digits `int()` accepts. */
const ND_RE = /^\p{Nd}$/u;

/**
 * `str.isprintable()` is the negation of this class, with one carve-out:
 * U+0020 SPACE is a Zs character yet Python calls it printable.
 */
const NON_PRINTABLE_RE = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;

/**
 * Split a string into code points.
 *
 * `Array.from` iterates by code point, so astral characters survive as one
 * element and lone surrogates (which our surrogateescape argv decoder can
 * produce) survive as one element too.  Never index by UTF-16 unit.
 */
export function toCodePoints(text) {
  return Array.from(text);
}

/** True if `ch` (a single code point) has the Unicode White_Space property. */
export function isPythonSpace(ch) {
  return WHITE_SPACE_RE.test(ch);
}

/** True if `ch` (a single code point) has General_Category=Nd. */
export function isDecimalDigit(ch) {
  return ND_RE.test(ch);
}

/** True if `ch` (a single code point) satisfies Python's `str.isprintable()`. */
export function isPrintable(ch) {
  if (ch === ' ') return true; // Zs, but Python considers plain space printable
  return !NON_PRINTABLE_RE.test(ch);
}

/**
 * Decimal value (0-9) of an Nd code point.
 *
 * Unicode lays Nd out in contiguous, decade-aligned runs, so the value of a
 * code point is its offset from the start of its run.  We find the run start by
 * walking back at most nine code points while the predecessor is still Nd.
 *
 * This is required because `parseInt` only understands ASCII digits and returns
 * NaN for e.g. U+0663 ARABIC-INDIC DIGIT THREE or U+1D7CE MATHEMATICAL BOLD
 * DIGIT ZERO.  Verified against U+0030, U+0039, U+0663, U+1045, U+FF19,
 * U+1D7CE and U+1E959.
 */
export function decimalDigitValue(ch) {
  const cp = ch.codePointAt(0);
  let start = cp;
  for (let back = 0; back < 9; back += 1) {
    const prev = start - 1;
    if (prev < 0) break;
    if (!ND_RE.test(String.fromCodePoint(prev))) break;
    start = prev;
  }
  return cp - start;
}

/**
 * Strip leading and trailing Unicode White_Space code points.
 *
 * Returns the trimmed *array of code points* because callers need to keep
 * scanning it character by character.
 */
export function stripPythonSpace(codePoints) {
  let lo = 0;
  let hi = codePoints.length;
  while (lo < hi && isPythonSpace(codePoints[lo])) lo += 1;
  while (hi > lo && isPythonSpace(codePoints[hi - 1])) hi -= 1;
  return codePoints.slice(lo, hi);
}

/**
 * Python 3 `repr()` / `str()` for the value shapes this program produces:
 * `str`, `bool`, `int` (arbitrary precision, modelled as BigInt), `list`
 * (Array) and `dict` (Map -- chosen because it preserves insertion order and
 * accepts boolean keys).
 */

import { isPrintable, toCodePoints } from './unicode.mjs';

/** Lower-case, zero-padded hex, as CPython's repr emits. */
function hex(cp, width) {
  return cp.toString(16).padStart(width, '0');
}

/**
 * CPython `unicode_repr()`.
 *
 * Quote selection: single quotes normally; if the string contains a `'` but no
 * `"`, switch the delimiter to `"` so the apostrophe needs no escape.  If it
 * contains both, stay on `'` and backslash-escape the apostrophes.  The
 * non-delimiter quote is never escaped.
 *
 *   a'b     -> "a'b"
 *   a"b     -> 'a"b'
 *   a'b"c   -> 'a\'b"c'
 *
 * Escaping: backslash and the delimiter get a backslash; TAB/LF/CR get their
 * short forms; every other non-printable code point is escaped numerically as
 * \xHH (< 0x100), \uHHHH (< 0x10000) or \UHHHHHHHH.  Printable non-ASCII --
 * including astral characters such as U+1F389 -- is emitted raw.
 */
export function reprStr(text) {
  const hasSingle = text.includes("'");
  const hasDouble = text.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let out = quote;
  for (const ch of toCodePoints(text)) {
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\t') {
      out += '\\t';
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (isPrintable(ch)) {
      out += ch;
    } else {
      const cp = ch.codePointAt(0);
      if (cp < 0x100) out += '\\x' + hex(cp, 2);
      else if (cp < 0x10000) out += '\\u' + hex(cp, 4);
      else out += '\\U' + hex(cp, 8);
    }
  }
  return out + quote;
}

/**
 * Python `int` repr: plain decimal, arbitrary precision, no `n` suffix and no
 * digit separators.  BigInt has no negative zero, so "-0" normalising to "0"
 * falls out for free.
 */
export function reprInt(value) {
  return value.toString();
}

/** Python `bool` repr. */
export function reprBool(value) {
  return value ? 'True' : 'False';
}

/** Python `list` repr: "[" + ", "-joined items + "]"; "[]" when empty. */
export function reprList(items) {
  return '[' + items.map((item) => pyRepr(item)).join(', ') + ']';
}

/**
 * Python `dict` repr: "{" + ", "-joined "KEY: VALUE" entries + "}"; "{}" when
 * empty.  Iteration follows the Map's insertion order, which is exactly what
 * CPython dicts guarantee.
 */
export function reprDict(map) {
  const parts = [];
  for (const [key, value] of map) {
    parts.push(pyRepr(key) + ': ' + pyRepr(value));
  }
  return '{' + parts.join(', ') + '}';
}

/** Dispatching `repr()`. */
export function pyRepr(value) {
  if (typeof value === 'bigint') return reprInt(value);
  if (typeof value === 'boolean') return reprBool(value);
  if (typeof value === 'string') return reprStr(value);
  if (Array.isArray(value)) return reprList(value);
  if (value instanceof Map) return reprDict(value);
  throw new TypeError('pyRepr: unsupported value ' + String(value));
}

/**
 * Dispatching `str()`, which is what `print()` uses.
 *
 * For every type here except `str` itself, `str()` and `repr()` coincide -- in
 * particular `str(dict)` is `repr(dict)`, and the dict's *members* are rendered
 * with `repr()`.  Only a bare top-level string prints unquoted.
 */
export function pyStr(value) {
  if (typeof value === 'string') return value;
  return pyRepr(value);
}

/**
 * Python exception objects and the exact stderr rendering the frozen
 * (PyInstaller) reference binary produces for an unhandled exception.
 */

import { writeStderr } from '../runtime/stdio.mjs';

/** Python's `ValueError`. */
export class PyValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'PyValueError';
    /** Name used in the traceback's last line. */
    this.pyType = 'ValueError';
  }
}

/**
 * Python's `SystemExit`.  argparse raises this from `parser.exit()`; the
 * interpreter unwinds and exits with `code` and prints no traceback.
 */
export class SystemExit extends Error {
  constructor(code) {
    super('SystemExit: ' + code);
    this.name = 'SystemExit';
    this.code = code;
  }
}

/**
 * Render the traceback for an unhandled exception, byte-for-byte as measured
 * from the reference binary:
 *
 *     Traceback (most recent call last):
 *       File "test5.py", line 8, in <module>
 *     ValueError: <message>
 *
 * NOTE: there is deliberately no source-echo line and no `^^^^^^` caret line.
 * A PyInstaller one-file build does not ship the .py source, so CPython's
 * traceback module cannot read line 8 back and emits neither the source line
 * nor the fine-grained caret underline.  Verified with `od -c` against the
 * reference; adding those lines would break parity.
 *
 * Line 8 of test5.py is the list comprehension
 * `numbers = [int(x) for x in args.a.split(',')]`, the only statement that can
 * raise here.
 */
export function formatTraceback(exc) {
  return (
    'Traceback (most recent call last):\n' +
    '  File "test5.py", line 8, in <module>\n' +
    exc.pyType + ': ' + exc.message + '\n'
  );
}

/**
 * The PyInstaller bootloader's own complaint, appended after the traceback.
 *
 * The number in `[PYI-<pid>:ERROR]` is the bootloader process id, so it changes
 * on every run.  We emit `process.pid` for the same reason; it is the one and
 * only byte range in this program's stderr that legitimately differs between
 * two runs with identical arguments.
 */
export function formatBootloaderError(pid = process.pid) {
  return (
    '[PYI-' + pid + ":ERROR] Failed to execute script 'test5' due to " +
    'unhandled exception!\n'
  );
}

/** Write the full crash report (traceback + bootloader line) to stderr. */
export function reportUnhandled(exc) {
  writeStderr(formatTraceback(exc) + formatBootloaderError());
}

/**
 * CPython's `int(str)` for base 10, returning a BigInt.
 *
 * Grammar accepted (identical to `PyLong_FromUnicodeObject` with base 10):
 *
 *     WS* [ '+' | '-' ]? DIGITS ( '_' DIGITS )* WS*
 *
 * where WS is a Unicode White_Space code point and DIGITS is one or more
 * General_Category=Nd code points.
 *
 * Consequences worth spelling out, all verified against the reference:
 *   * Surrounding whitespace is stripped, but no whitespace may appear between
 *     the sign and the digits or inside the digits: "- 3", "+ 3", "3 4" and
 *     "1 000" all raise.
 *   * Any Nd digit contributes its decimal value, and scripts may be mixed
 *     inside one literal: "٣1" == 31, "１٣" == 13.
 *   * Non-Nd numerics are rejected: U+00B2 (superscript two), U+00BD (one half)
 *     and U+2165 (Roman numeral six) all raise.
 *   * Underscores must be single and strictly between digits: "1_0" is fine
 *     while "1__0", "_1", "1_", "+_1" and "-_1" all raise.
 */

import {
  decimalDigitValue,
  isDecimalDigit,
  stripPythonSpace,
  toCodePoints,
} from './unicode.mjs';
import { PyValueError } from './exceptions.mjs';
import { reprStr } from './repr.mjs';

/**
 * CPython's default `sys.int_max_str_digits`.  Decimal literals with more than
 * this many digits are refused outright as a denial-of-service guard.
 */
export const INT_MAX_STR_DIGITS = 4300;

/**
 * `ValueError: invalid literal for int() with base 10: <repr>`
 *
 * The repr is of the ORIGINAL, UNSTRIPPED argument -- surrounding whitespace and
 * all.  That is why U+00A0 shows up escaped as `\xa0` in the message even though
 * `int()` would have stripped it had the rest of the literal been valid.
 */
function invalidLiteral(original) {
  return new PyValueError(
    'invalid literal for int() with base 10: ' + reprStr(original),
  );
}

/**
 * `ValueError: Exceeds the limit (4300 digits) ...` -- a single line.
 *
 * Digit-count semantics, all verified:
 *   * leading zeros count (4400 "0" characters reports 4400 digits, even though
 *     the value is 0);
 *   * underscores do NOT count (2200 "9_" pairs plus a "9" is 2201 digits and
 *     parses fine);
 *   * the sign does NOT count;
 *   * surrounding whitespace is irrelevant.
 */
function exceedsLimit(digitCount) {
  return new PyValueError(
    'Exceeds the limit (' +
      INT_MAX_STR_DIGITS +
      ') digits) for integer string conversion: value has ' +
      digitCount +
      ' digits; use sys.set_int_max_str_digits() to increase the limit',
  );
}

/**
 * Convert `text` to a BigInt using Python's base-10 `int()` rules.
 *
 * @throws {PyValueError}
 */
export function pyInt(text) {
  const body = stripPythonSpace(toCodePoints(text));

  let i = 0;
  let negative = false;
  if (i < body.length && (body[i] === '+' || body[i] === '-')) {
    negative = body[i] === '-';
    i += 1;
  }

  // ASCII-normalised digits, so the final BigInt() call is cheap even for the
  // 4300-digit maximum.  Every Nd code point is mapped through its decimal
  // value, which is what makes mixed-script literals work.
  const digits = [];
  let expectDigit = true; // true at the start of the number and after each '_'

  for (; i < body.length; i += 1) {
    const ch = body[i];
    if (isDecimalDigit(ch)) {
      digits.push(String(decimalDigitValue(ch)));
      expectDigit = false;
    } else if (ch === '_' && !expectDigit) {
      // A '_' is only legal directly after a digit, and must itself be followed
      // by a digit -- enforced by leaving `expectDigit` true.
      expectDigit = true;
    } else {
      throw invalidLiteral(text);
    }
  }

  // Trailing '_' (expectDigit still set) or no digits at all -- covers "", " ",
  // "1_", "_1", "+", "-" and "+_1".
  if (expectDigit || digits.length === 0) {
    throw invalidLiteral(text);
  }

  // PRECEDENCE: syntactic validity is checked first.  A string that is both
  // malformed and over-long (e.g. 4301 nines followed by "a") reports the
  // "invalid literal" error, never the digit-limit one.
  if (digits.length > INT_MAX_STR_DIGITS) {
    throw exceedsLimit(digits.length);
  }

  const magnitude = BigInt(digits.join(''));
  return negative ? -magnitude : magnitude;
}

/**
 * A faithful port of the parts of Python's `textwrap` module that argparse's
 * `HelpFormatter` relies on: `textwrap.wrap(text, width)` with stock options
 * (`replace_whitespace=True`, `drop_whitespace=True`, `break_long_words=True`,
 * `break_on_hyphens=True`, no indents).
 *
 * This matters because the reference honours `$COLUMNS`: at `COLUMNS=20` the
 * help text really is rewrapped, and "Comma-separated numbers" really does
 * break after the hyphen into "Comma-" / "separated" / "numbers".  A naive
 * space-only wrapper gets that wrong.
 */

/** `textwrap.TextWrapper.whitespace` -- the ASCII whitespace it folds away. */
const WHITESPACE = '\t\n\v\f\r ';

/**
 * Port of `TextWrapper.wordsep_re`.
 *
 * The original is built from `\w` and `[^\d\W]`, which are Unicode-aware in
 * Python.  Here they are ASCII, which is safe because the only strings ever fed
 * to this wrapper are the ASCII help/usage constants defined in
 * `lib/cli/parser.mjs`.
 *
 * The three alternatives are: a run of whitespace; an em-dash between words; or
 * a word, optionally split just after an interior hyphen (only when at least two
 * letters precede the hyphen and at least two letters follow it, which is what
 * turns "Comma-separated" into "Comma-" + "separated").
 */
const WORD_SEP_RE = new RegExp(
  '(' +
    // any whitespace
    '[\\t\\n\\v\\f\\r ]+' +
    '|' +
    // em-dash between words
    '(?<=[\\w!"\'&.,?])-{2,}(?=\\w)' +
    '|' +
    // word, possibly hyphenated
    '[^\\t\\n\\v\\f\\r ]+?(?:' +
    // hyphenated word
    '-(?:(?<=[a-zA-Z_]{2}-)|(?<=[a-zA-Z_]-[a-zA-Z_]-))(?=[a-zA-Z_]-?[a-zA-Z_])' +
    '|' +
    // end of word
    '(?=[\\t\\n\\v\\f\\r ]|$)' +
    '|' +
    // em-dash
    '(?<=[\\w!"\'&.,?])(?=-{2,}\\w)' +
    ')' +
    ')',
  'g',
);

/**
 * Python's `re.split` with a capturing pattern: the separators are interleaved
 * with the (possibly empty) text between them.  Because `WORD_SEP_RE` matches
 * both words and whitespace runs, the in-between pieces are normally empty and
 * get filtered out, exactly as `TextWrapper._split` does.
 */
function splitChunks(text) {
  const chunks = [];
  let last = 0;
  WORD_SEP_RE.lastIndex = 0;
  let match = WORD_SEP_RE.exec(text);
  while (match !== null) {
    chunks.push(text.slice(last, match.index));
    chunks.push(match[0]);
    last = match.index + match[0].length;
    // Guard against a zero-length match looping forever.
    if (match[0].length === 0) WORD_SEP_RE.lastIndex += 1;
    match = WORD_SEP_RE.exec(text);
  }
  chunks.push(text.slice(last));
  return chunks.filter((chunk) => chunk !== '');
}

/** `TextWrapper._munge_whitespace`: expand tabs, then map whitespace to space. */
function mungeWhitespace(text) {
  let expanded = '';
  for (const ch of text) {
    if (ch === '\t') {
      // expandtabs(tabsize=8)
      const column = expanded.length - (expanded.lastIndexOf('\n') + 1);
      expanded += ' '.repeat(8 - (column % 8));
    } else {
      expanded += ch;
    }
  }
  let out = '';
  for (const ch of expanded) out += WHITESPACE.includes(ch) ? ' ' : ch;
  return out;
}

/** `TextWrapper._handle_long_word` with break_long_words + break_on_hyphens. */
function handleLongWord(reversedChunks, curLine, curLen, width) {
  const spaceLeft = width < 1 ? 1 : width - curLen;
  const chunk = reversedChunks[reversedChunks.length - 1];
  let end = spaceLeft;
  if (chunk.length > spaceLeft) {
    // Break after the last hyphen that fits, but only when something other than
    // hyphens precedes it.
    const hyphen = chunk.lastIndexOf('-', spaceLeft - 1);
    if (hyphen > 0 && Array.from(chunk.slice(0, hyphen)).some((c) => c !== '-')) {
      end = hyphen + 1;
    }
  }
  curLine.push(chunk.slice(0, end));
  reversedChunks[reversedChunks.length - 1] = chunk.slice(end);
}

/** `TextWrapper._wrap_chunks` for the default (indent-free) configuration. */
function wrapChunks(chunks, width) {
  const lines = [];
  const stack = chunks.slice().reverse();

  while (stack.length > 0) {
    const curLine = [];
    let curLen = 0;

    // Drop a leading whitespace chunk, except at the very start of the text.
    if (stack[stack.length - 1].trim() === '' && lines.length > 0) stack.pop();

    while (stack.length > 0) {
      const len = stack[stack.length - 1].length;
      if (curLen + len <= width) {
        curLine.push(stack.pop());
        curLen += len;
      } else {
        break;
      }
    }

    // Next chunk cannot fit on any line -- split it.
    if (stack.length > 0 && stack[stack.length - 1].length > width) {
      handleLongWord(stack, curLine, curLen, width);
      curLen = curLine.reduce((sum, chunk) => sum + chunk.length, 0);
    }

    // Never let a line end in whitespace.
    if (curLine.length > 0 && curLine[curLine.length - 1].trim() === '') {
      curLen -= curLine[curLine.length - 1].length;
      curLine.pop();
    }

    if (curLine.length > 0) lines.push(curLine.join(''));
  }

  return lines;
}

/** `textwrap.wrap(text, width)`. */
export function wrap(text, width) {
  if (width <= 0) {
    throw new Error('invalid width ' + width + ' (must be > 0)');
  }
  return wrapChunks(splitChunks(mungeWhitespace(text)), width);
}

/**
 * Python's `shutil.get_terminal_size()`, which is what argparse consults to
 * decide the help/usage wrap width.
 *
