      lo2 = 0xa0;
      hi2 = 0xbf; // reject overlong
    } else if (b0 === 0xed) {
      need = 2;
      lo2 = 0x80;
      hi2 = 0x9f; // reject UTF-16 surrogates
    } else if (b0 >= 0xe1 && b0 <= 0xef) {
      need = 2;
      lo2 = 0x80;
      hi2 = 0xbf;
    } else if (b0 === 0xf0) {
      need = 3;
      lo2 = 0x90;
      hi2 = 0xbf; // reject overlong
    } else if (b0 === 0xf4) {
      need = 3;
      lo2 = 0x80;
      hi2 = 0x8f; // reject > U+10FFFF
    } else if (b0 >= 0xf1 && b0 <= 0xf3) {
      need = 3;
      lo2 = 0x80;
      hi2 = 0xbf;
