    if (!valid) continue;

    let cp = b0 & (need === 1 ? 0x1f : need === 2 ? 0x0f : 0x07);
    for (let k = 1; k <= need; k += 1) cp = (cp << 6) | (bytes[i + k] & 0x3f);
