 *     what the reference's output shows -- `--a 2,1` prints
 *     `{True: [2], False: [1]}`, not a sorted `{False: ..., True: ...}`.
 *
 * The source is iterated exactly once, in order.
 */
export function bucketize(src, key = (value) => Boolean(value), valueTransform = null, keyFilter = null) {
  if (typeof key !== 'function') {
    throw new TypeError('expected callable key function');
  }

  const buckets = new Map();
  for (const item of src) {
    const keyValue = key(item);
    let bucket = buckets.get(keyValue);
    if (bucket === undefined) {
      bucket = [];
      buckets.set(keyValue, bucket);
    }
    bucket.push(valueTransform === null ? item : valueTransform(item));
