        return startIndex + 1;
      }
      // "--help=x": a long option that takes no value was given one.
      throw new ArgumentError(action, 'ignored explicit argument ' + reprStr(explicitArg));
    }

    const start = startIndex + 1;
    const argCount = ArgumentParser._matchArgument(action, pattern.slice(start));
    const stop = start + argCount;
    this._takeAction(action, argStrings.slice(start, stop), namespace, seenActions);
    return stop;
  }
};

