/** `consume_optional` -> index just past this option's consumed values. */
const consumeOptional = (startIndex) => {
  let [action, optionString, sep, explicitArg] = optionStringIndices.get(startIndex);

  // Actions are queued rather than run immediately, exactly as argparse does,
  // because a packed short-option string such as `-hx` may resolve into
  // several actions -- and because the unresolved tail is reported as an
  // extra WITHOUT cancelling the actions already recognised.  That is why
  // `-ha` still prints the help and exits 0 instead of erroring.
  const actionTuples = [];
  let stop;

  for (;;) {
    // An unrecognised option: park it and move on (step 3 of the precedence).
    if (action === null) {
      extras.push(argStrings[startIndex]);
      return startIndex + 1;
    }

    if (explicitArg !== null) {
      const argCount = ArgumentParser._matchArgument(action, 'A');

      if (argCount === 0 && !PREFIX_CHARS.includes(optionString[1]) && explicitArg !== '') {
        // A short option that takes no value was handed one.  If the value
        // was attached with "=" (sep) or itself starts with "-", that is an
        // outright error; otherwise argparse re-reads the tail as further
        // packed short options.
        if (sep || PREFIX_CHARS.includes(explicitArg[0])) {
          throw new ArgumentError(action, 'ignored explicit argument ' + reprStr(explicitArg));
        }
        actionTuples.push([action, [], optionString]);
        const char = optionString[0];
        const nextOptionString = char + explicitArg[0];
        if (this.optionStringActions.has(nextOptionString)) {
          action = this.optionStringActions.get(nextOptionString);
          optionString = nextOptionString;
          explicitArg = explicitArg.slice(1);
          if (explicitArg === '') {
            sep = null;
            explicitArg = null;
          } else if (explicitArg[0] === '=') {
            sep = '=';
            explicitArg = explicitArg.slice(1);
          } else {
            sep = '';
          }
          continue;
        }
        // Tail is not a known option: report it as an extra and still run
        // whatever was recognised before it.
        extras.push(char + explicitArg);
        stop = startIndex + 1;
        break;
      }

      if (argCount === 1) {
        // "--a=1,2" and even "--a=" (empty value) land here.
        actionTuples.push([action, [explicitArg], optionString]);
        stop = startIndex + 1;
        break;
      }

      // "--help=x" and "-h=1": a value-less option was given a value.
      throw new ArgumentError(action, 'ignored explicit argument ' + reprStr(explicitArg));
    }

    const start = startIndex + 1;
    const argCount = ArgumentParser._matchArgument(action, pattern.slice(start));
    stop = start + argCount;
    actionTuples.push([action, argStrings.slice(start, stop), optionString]);
    break;
  }

  for (const [queuedAction, args] of actionTuples) {
    this._takeAction(queuedAction, args, namespace, seenActions);
  }
  return stop;
};
